package com.axsos.Life.models; import jakarta.persistence.*; import java.time.LocalDate; import java.util.*; import static com.axsos.Life.models.Enums.*;
@Entity @Table(name="roadmaps",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","roadmap_date"})) public class Roadmap extends BaseEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @Column(name="roadmap_date") private LocalDate roadmapDate;
 private Integer targetKcal; private Integer targetWaterMl; private Double targetProtein; private Double targetCarbs; private Double targetFat; @Column(length=500) private String primaryGoalText; @Column(length=4000) private String aiSummary; private String triggerSource; @Enumerated(EnumType.STRING) private AiStatus aiStatus;
 @OneToMany(mappedBy="roadmap",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("displayOrder asc") private List<RoadmapItem> items=new ArrayList<>();
 public Long getId(){return id;} public void setId(Long v){id=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public LocalDate getRoadmapDate(){return roadmapDate;} public void setRoadmapDate(LocalDate v){roadmapDate=v;} public Integer getTargetKcal(){return targetKcal;} public void setTargetKcal(Integer v){targetKcal=v;} public Integer getTargetWaterMl(){return targetWaterMl;} public void setTargetWaterMl(Integer v){targetWaterMl=v;} public Double getTargetProtein(){return targetProtein;} public void setTargetProtein(Double v){targetProtein=v;} public Double getTargetCarbs(){return targetCarbs;} public void setTargetCarbs(Double v){targetCarbs=v;} public Double getTargetFat(){return targetFat;} public void setTargetFat(Double v){targetFat=v;} public String getPrimaryGoalText(){return primaryGoalText;} public void setPrimaryGoalText(String v){primaryGoalText=v;} public String getAiSummary(){return aiSummary;} public void setAiSummary(String v){aiSummary=v;} public String getTriggerSource(){return triggerSource;} public void setTriggerSource(String v){triggerSource=v;} public AiStatus getAiStatus(){return aiStatus;} public void setAiStatus(AiStatus v){aiStatus=v;} public List<RoadmapItem> getItems(){return items;} public void setItems(List<RoadmapItem> v){items=v;}
}
